def certify_strategy_seventy_six_source():
    """Verify ordered declarations, their anchor and fresh native source bytes."""
    self_relative = 'src/backend/backtest_strategy_seventy_six_certification.py'
    # The only partial module is this self-anchored metadata envelope. Every
    # operational dependency, including the complete legacy V4 grammar guards,
    # receives a whole-module digest in the successor's independent closure.
    symbol_leaves = {
        'src/backend/backtest_strategy_seventy_six_certification.py': ('certify_strategy_seventy_six_source',),
    }
    metadata_anchor = '28f454faaadbb25b62ab0add91a62897f2046feb2efe1f35ee87b6b7eff365c0'
    if (type(REQUIRED_SOURCE_FILES) is not tuple
            or any(type(path) is not str for path in REQUIRED_SOURCE_FILES)
            or len(set(REQUIRED_SOURCE_FILES)) != len(REQUIRED_SOURCE_FILES)
            or type(STRATEGY76_SOURCE_AST) is not dict
            or tuple(STRATEGY76_SOURCE_AST) != REQUIRED_SOURCE_FILES):
        raise ValueError('Strategy76 complete source review is not sealed')
    for relative, expected in STRATEGY76_SOURCE_AST.items():
        if relative in symbol_leaves:
            if type(expected) is not dict or tuple(expected) != symbol_leaves[relative]:
                raise ValueError('Strategy76 source selector shape changed: '+relative)
            values = tuple(expected.values())
        else:
            if type(expected) is not str:
                raise ValueError('Strategy76 source digest shape changed: '+relative)
            values = (expected,)
        if any(type(value) is not str or len(value) != 64
               or any(c not in '0123456789abcdef' for c in value) for value in values):
            raise ValueError('Strategy76 source digest is malformed: '+relative)
    metadata = dict(required=REQUIRED_SOURCE_FILES,
        sources={path:value for path,value in STRATEGY76_SOURCE_AST.items() if path != self_relative},
        symbols=symbol_leaves)
    if sha256(json.dumps(metadata,sort_keys=True,separators=(',', ':')).encode()).hexdigest() != metadata_anchor:
        raise ValueError('Strategy76 source metadata anchor changed')
    root = Path(__file__).parents[2]
    observed = []
    for relative in REQUIRED_SOURCE_FILES:
        expected = STRATEGY76_SOURCE_AST[relative]
        source = (root/relative).read_text(encoding='utf-8')
        try:
            tree = ast.parse(source)
        except SyntaxError as exc:
            raise ValueError('Strategy76 source cannot be parsed: '+relative) from exc
        if relative in symbol_leaves:
            for symbol, digest in expected.items():
                kind = ast.ClassDef if relative == 'src/trading_runtime/squeeze_ladder_automatic.py' else ast.FunctionDef
                nodes = [node for node in tree.body if isinstance(node, kind) and node.name == symbol]
                if len(nodes) != 1 or sha256(ast.unparse(nodes[0]).encode()).hexdigest() != digest:
                    raise ValueError('Strategy76 pinned source changed: '+relative+':'+symbol)
        elif sha256(ast.unparse(tree).encode()).hexdigest() != expected:
            raise ValueError('Strategy76 pinned source changed: '+relative)
        if relative == self_relative:
            envelope = tree.body
            imports = ('from hashlib import sha256', 'import json',
                       'from pathlib import Path', 'import ast')
            if (len(envelope) != 8
                    or not isinstance(envelope[0],ast.Expr)
                    or not isinstance(envelope[0].value,ast.Constant)
                    or envelope[0].value.value != 'Closed selected consecutive original-risk failure source authority; publication is separate.'
                    or tuple(ast.unparse(node) for node in envelope[1:5]) != imports
                    or any(not isinstance(node,ast.Assign) or len(node.targets) != 1
                           or not isinstance(node.targets[0],ast.Name)
                           for node in envelope[5:7])
                    or tuple(node.targets[0].id for node in envelope[5:7])
                       != ('REQUIRED_SOURCE_FILES','STRATEGY76_SOURCE_AST')
                    or not isinstance(envelope[7],ast.FunctionDef)
                    or envelope[7].name != 'certify_strategy_seventy_six_source'
                    or envelope[7].args.posonlyargs or envelope[7].args.args
                    or envelope[7].args.kwonlyargs or envelope[7].args.vararg
                    or envelope[7].args.kwarg or envelope[7].args.defaults
                    or envelope[7].args.kw_defaults):
                raise ValueError('Strategy76 own source module envelope changed')
            declarations = {}
            for node in tree.body:
                if (isinstance(node,ast.Assign) and len(node.targets) == 1
                        and isinstance(node.targets[0],ast.Name)
                        and node.targets[0].id in ('REQUIRED_SOURCE_FILES','STRATEGY76_SOURCE_AST')):
                    name = node.targets[0].id
                    if name in declarations:
                        raise ValueError('Strategy76 fresh source declaration duplicated')
                    if name == 'STRATEGY76_SOURCE_AST':
                        if (not isinstance(node.value, ast.Dict)
                                or len(node.value.keys) != len(REQUIRED_SOURCE_FILES)
                                or any(not isinstance(key, ast.Constant) or type(key.value) is not str
                                       for key in node.value.keys)
                                or tuple(key.value for key in node.value.keys) != REQUIRED_SOURCE_FILES):
                            raise ValueError('Strategy76 fresh source map shape changed')
                    declarations[name] = ast.literal_eval(node.value)
            if (set(declarations) != {'REQUIRED_SOURCE_FILES','STRATEGY76_SOURCE_AST'}
                    or declarations['REQUIRED_SOURCE_FILES'] != REQUIRED_SOURCE_FILES
                    or declarations['STRATEGY76_SOURCE_AST'] != STRATEGY76_SOURCE_AST):
                raise ValueError('Strategy76 fresh source declarations differ')
        observed.append((relative, sha256(source.encode()).hexdigest()))
    return sha256(json.dumps(observed,separators=(',', ':')).encode()).hexdigest()
